from pathlib import Path
from dataclasses import replace
from unittest.mock import patch
import io,hashlib,json,sys,importlib.metadata
import numpy as np
from training.holistic_migration import dataset as d
from training.holistic_migration.features import pack_frame,resample_frames
from training.holistic_migration.sequence import prepare_capture,ObservationClock,prepare_image
from training.holistic_migration.tests.test_sequence import frames
from training.holistic_migration.tests.test_dataset import integer_frame
r=Path.cwd();data=r.parent/'holistic-migration-data';w=data/'evidence/task-c-fix1-00ffe6b02d21421f86d86ba5fc208a26';s=w/'synthetic-corrected'
# Current real metadata only; no raw-media open or native tracker construction.
g=d.preflight(partition_manifest=data/'candidate-partitions-v1.json',source_inventory=data/'verified-video-byte-inventory.json',decode_summary=data/'decoded-source-audit-v1/summary.json',raw_root=data/'clips_raw',classes=r/'training/preprocessing/selected_classes.json',model=data/'holistic_landmarker.task')
assert len(g.rows)==1016 and len(g.classes)==50 and g.classes[25]['original_id']==49 and g.classes[25]['label']=='TODAY'
from collections import Counter
assert Counter(row['partition'] for row in g.rows)==dict(fit=663,validation=150,test=203)
for line in (r/'training/holistic_migration/requirements.txt').read_text().splitlines():
 if '==' in line:
  name,version=line.split('==');assert importlib.metadata.version(name)==version
real_metadata={'sources':len(g.rows),'classes':len(g.classes),'partitions':dict(Counter(row['partition'] for row in g.rows)),'dense25':g.classes[25],'runtime':d.runtime_binding(),'contract_sha256':d.canonical_hash(g.contract),'runtime_sha256':d.canonical_hash(g.runtime),'opened_raw_videos':0,'inference_calls':0}
# Read retained corrected producer/bundle; exercise public consumer, not regenerate.
g,manifest,rows=d.validate_campaign(s/'campaign');bundle=d.load_json(s/'bundle/data_manifest.json')
assert manifest['evidence_kind']==bundle['evidence_kind']=='synthetic_in_process' and bundle['training_qualified'] is False
assert bundle['graph']==d.graph_receipt(g) and len(bundle['classes'])==50
for name,record in bundle['artifacts'].items():assert d.sha256(s/'bundle'/name)==record['sha256']
count=0;shapes={}
for part in d.PARTITIONS:
 selected=[row for row in rows if row['partition']==part]
 x=np.load(s/'bundle'/f'X_{part}.npy',allow_pickle=False);y=np.load(s/'bundle'/f'y_{part}.npy',allow_pickle=False);ids=np.load(s/'bundle'/f'clip_ids_{part}.npy',allow_pickle=False)
 assert x.shape==(50,30,153) and x.dtype==np.float32 and y.dtype==np.int64
 assert ids.tolist()==[row['clip_id'] for row in selected] and y.tolist()==[row['dense_id'] for row in selected]
 for i,row in enumerate(selected):
  np.testing.assert_array_equal(x[i],prepare_capture(d.read_raw(s/'campaign'/row['raw_file'],row['raw_sha256'])).tensor);count+=1
 shapes[part]=list(x.shape)
 assert bundle['eligibility']['partitions'][part]==dict(declared=50,eligible=50,ineligible=0,reasons={})
# Independently compare every retained raw scalar to synthetic controls.
times=[0,67,133,200,267,333,400,467]
faces=[None,np.empty((0,3),np.float64),np.arange(478*3,dtype=np.float64).reshape(478,3)/13,np.full((2,3),-.125),np.array([[2**64-2048,0,0]],np.uint64),np.array([[-(2**63),2**53+2,0]],np.int64),None,np.array([[0.,-0.,.5]],np.float64)]
observations=0
for name in ['campaign','diagnostic']:
 rr=[json.loads(line) for line in (s/name/'rows.jsonl').read_text().splitlines()]
 for row in rr:
  if 'raw_file' not in row:continue
  back=d.read_raw(s/name/row['raw_file'],row['raw_sha256']);assert len(back)==8
  for i,frame in enumerate(back):
   expected=replace(frames()[i],timestamp_ms=times[i],face=faces[i]);assert frame.timestamp_ms==expected.timestamp_ms
   for component in ['pose','left_hand','right_hand','face']:
    source,stored=getattr(expected,component),getattr(frame,component)
    if source is None:assert stored is None
    else:
     assert source.shape==stored.shape and stored.dtype==np.float64
     for a,b in zip(source.flat,stored.flat):
      if source.dtype.kind in 'iu':assert float(b).as_integer_ratio()==(int(a),1)
      else:assert float(b).hex()==float(a).hex()
   np.testing.assert_array_equal(pack_frame(expected),pack_frame(frame));observations+=1
 diag=d.load_json(s/'diagnostic/extraction_manifest.json')
assert diag['status']=='diagnostic_fit_only' and diag['full_campaign_qualification'] is False
assert diag['counts']==dict(declared=150,selected=50,processed=50,errors=0)
diagrows=[json.loads(line) for line in (s/'diagnostic/rows.jsonl').read_text().splitlines()]
selected=d.load_json(s/'diagnostic/selected_ids.json')
expected=sorted(min(row['clip_id'] for row in g.rows if row['partition']=='fit' and row['dense_id']==i) for i in range(50))
assert selected==expected and Counter(row['status'] for row in diagrows)==dict(eligible=50,not_selected=100)
try:d.validate_campaign(s/'diagnostic')
except ValueError as error:assert 'diagnostic refused' in str(error)
else:raise AssertionError('diagnostic accepted')
try:d.validate_campaign(data/'evidence/task-c-20261113T044844/synthetic-smoke/campaign')
except ValueError as error:assert 'contract' in str(error);old_refusal=str(error)
else:raise AssertionError('stale contract accepted')
# A focused in-memory public codec probe; only its NPZ transport is redirected.
p=Path.home()/'.hermes/cache/scratch/task-c-review-2-memory-only.npz';assert not p.exists()
transport={};realopen=Path.open;realload=np.load;realsha=d.sha256
class MemoryWrite(io.BytesIO):
 def __exit__(self,*args):transport['bytes']=self.getvalue();self.close()
def opened(path,mode='r',*args,**kwargs):
 if path==p:
  assert mode=='xb';transport['opens']=transport.get('opens',0)+1;return MemoryWrite()
 return realopen(path,mode,*args,**kwargs)
def loaded(path,*args,**kwargs):
 return realload(io.BytesIO(transport['bytes']) if isinstance(path,Path) and path==p else path,*args,**kwargs)
def checksum(path):return hashlib.sha256(transport['bytes']).hexdigest() if path==p else realsha(path)
controls=[(np.int64,-(2**63),True),(np.int64,-(2**63)+1,False),(np.int64,2**53+1,False),(np.int64,2**53+2,True),(np.int64,2**63-1024,True),(np.int64,2**63-1,False),(np.uint64,2**63,True),(np.uint64,2**64-2048,True),(np.uint64,2**64-2,False),(np.uint64,2**64-1,False)]
accepted=rejected=0
with patch.object(Path,'open',opened),patch.object(np,'load',loaded),patch.object(d,'sha256',checksum):
 for component in ['pose','left_hand','right_hand','face']:
  for dtype,value,representable in controls:
   source=integer_frame(component,dtype,[value]);before=transport.get('opens',0)
   try:back=d.read_raw(p,d.write_raw(p,[source]))[0]
   except ValueError as error:
    assert not representable and 'losslessly' in str(error);assert transport.get('opens',0)==before;rejected+=1
   else:
    assert representable and transport['opens']==before+1
    for a,b in zip(getattr(source,component).flat,getattr(back,component).flat):assert float(b).as_integer_ratio()==(int(a),1)
    np.testing.assert_array_equal(pack_frame(source),pack_frame(back));accepted+=1
assert not p.exists()
# Sequence and accepted-A interface boundary with exact current shared caller behavior.
clock=ObservationClock();assert clock.admit(0) and not clock.admit(1)
before=clock.__dict__.copy()
for bad in [True,1.0,-1,0,1]:
 try:clock.admit(bad)
 except ValueError:pass
 else:raise AssertionError('bad clock timestamp admitted')
 assert clock.__dict__==before
assert clock.admit(67)
f=frames(12)
for i in [0,1,4,6,10,11]:f[i]=replace(f[i],left_hand=None)
capture=prepare_capture(f);np.testing.assert_array_equal(capture.tensor,resample_frames(f[2:10]));assert (capture.source_observation_count,capture.observation_count,capture.hand_count)==(12,8,6)
import cv2
rgb=np.arange(18*40*3,dtype=np.uint8).reshape(18,40,3)[:,::-1];rgb.setflags(write=False)
np.testing.assert_array_equal(prepare_image(rgb,cv2),cv2.resize(rgb,(640,360),interpolation=cv2.INTER_AREA))
assert 'mediapipe' not in sys.modules
print(json.dumps({'current_metadata':real_metadata,'retained_consumer':{'exact_tensors':count,'exact_raw_observations':observations,'artifact_digests':len(bundle['artifacts']),'shapes':shapes,'full_counts':manifest['counts'],'diagnostic_counts':diag['counts'],'diagnostic_status_counts':dict(Counter(row['status'] for row in diagrows)),'diagnostic_literal_first_fit_selection':True,'diagnostic_refused':True,'old_contract_refusal':old_refusal},'focused_memory_codec':{'component_value_cases':len(controls)*4,'accepted_exact':accepted,'rejected_before_open':rejected,'files_created':0,'source_changes':0},'sequence_interfaces':{'invalid_clock_inputs_without_mutation':5,'strided_readonly_asymmetric_RGB_exact':True,'trimmed_shared_resampler_exact':True,'source_bounded_hand_counts':[12,8,6]},'native_inference_calls':0,'mediapipe_imported':False}))
